import manifest from "./gallery.json";

export type GalleryItem = {
  id: string;
  collection: string;
  brand: string;
  group: string | null;
  title: string | null;
  tag: string | null;
  width: number;
  height: number;
  /** Full-page screenshot: thumb is cropped to the top, lightbox scrolls. */
  tall: boolean;
  thumb: string;
  full: string;
};

export type CollectionGroup = "graphic" | "uiux" | "video";

