export const videos: Video[] = videoGroups.flatMap((g) => g.videos);

const items = manifest.items as GalleryItem[];

export function itemsFor(slug: string): GalleryItem[] {
  return items.filter((i) => i.collection === slug);
}

export function countFor(slug: string): number {
  return slug === "video" ? videos.length : itemsFor(slug).length;
}

export function coverFor(c: Collection): GalleryItem | undefined {
  if (c.coverFrom) {
    const designed = itemsFor("dev-screens").find((i) => i.full.includes(c.coverFrom as string));
    if (designed) return designed;
  }
  const list = itemsFor(c.slug);
  if (c.cover) {
    const hit = list.find((i) => i.full.includes(c.cover as string));
    if (hit) return hit;
  }
  return list[0];
}

/** YouTube poster for the video collection tile. */
export function videoCover(): string | undefined {
  const first = videos.find((v) => v.youtubeId);
  return first ? `https://i.ytimg.com/vi/${first.youtubeId}/hqdefault.jpg` : undefined;
}

export function brandsFor(slug: string): string[] {
  if (slug === "video") return videoGroups.map((g) => g.label.split(" — ")[0]);
  return [...new Set(itemsFor(slug).map((i) => i.brand))];
}

export function collectionsIn(group: CollectionGroup): Collection[] {
  return collections.filter((c) => c.group === group);
}

export function collectionBySlug(slug: string): Collection | undefined {
  return collections.find((c) => c.slug === slug);
}

/** Display title for a piece — falls back to "<brand> nn" for untitled exports. */
export function itemTitle(item: GalleryItem, index: number): string {
  return item.title ?? `${item.brand} ${String(index + 1).padStart(2, "0")}`;
}

/** Only the design division's collections — development screens live in the same manifest. */
export const totalDesignPieces =
  collections.reduce((n, c) => n + (c.slug === "video" ? 0 : itemsFor(c.slug).length), 0) +
  videos.length;

/** Screenshot for a development project card: matched by filename in the given collections. */
export function screenFor(match: string, collections: string[] = ["dev-screens"]): GalleryItem | undefined {
  for (const slug of collections) {
    const hit = itemsFor(slug).find((i) => i.full.includes(match));
    if (hit) return hit;
  }
  return undefined;
}
